1: /**
2:  * scripts/verify-prod-ipk.js
3:  * Production IPK Package Verification Harness for com.cinejoy.tv
4:  *
5:  * Verifies dist/com.cinejoy.tv_1.0.0_all.ipk:
6:  *   1. File existence and minimum size
7:  *   2. Debian ar container format (debian-binary, control.tar.gz, data.tar.gz)
8:  *   3. Debian control metadata (Package: com.cinejoy.tv, Version: 1.0.0, Architecture: all)
9:  *   4. Data archive layout:
10:  *      - Application: usr/palm/applications/com.cinejoy.tv/
11:  *      - Package mapping: usr/palm/packages/com.cinejoy.tv/packageinfo.json
12:  *      - Service: usr/palm/services/com.cinejoy.tv.service/
13:  *      - Service assets: crush.wasm, http-client.js, resolver.js, hls-proxy.js, index.js, services.json
14:  *   5. Exact byte size check for crush.wasm (67,222 bytes)
15:  *   6. Manifest cross-validation (packageinfo.json ↔ appinfo.json ↔ services.json)
16:  *   7. SDK tooling compatibility (ares-package -I)
17:  *
18:  * Compatible with Node 12.22.2 through modern Node.js
19:  */
20: 
21: 'use strict';
22: 
23: const fs = require('fs');
24: const path = require('path');
25: const { execSync } = require('child_process');
26: 
27: const defaultIpkPath = fs.existsSync(path.join(process.cwd(), 'dist', 'com.cinejoy.tv_1.0.1_all.ipk'))
28:   ? path.join(process.cwd(), 'dist', 'com.cinejoy.tv_1.0.1_all.ipk')
29:   : path.join(process.cwd(), 'dist', 'com.cinejoy.tv_1.0.0_all.ipk');
30: const targetIpk = process.argv[2] ? path.resolve(process.argv[2]) : defaultIpkPath;
31: 
32: const C = {
33:   reset: '\x1b[0m',
34:   bold: '\x1b[1m',
35:   green: '\x1b[32m',
36:   red: '\x1b[31m',
37:   cyan: '\x1b[36m',
38:   gray: '\x1b[90m'
39: };
40: 
41: function assert(condition, message) {
42:   if (!condition) {
43:     throw new Error(message || 'Assertion failed');
44:   }
45: }
46: 
47: function runCommand(cmd) {
48:   try {
49:     return execSync(cmd, { stdio: ['ignore', 'pipe', 'pipe'] }).toString('utf8');
50:   } catch (err) {
51:     throw new Error('Command failed: ' + cmd + '\n' + (err.stderr ? err.stderr.toString('utf8') : err.message));
52:   }
53: }
54: 
55: function runBufferCommand(cmd) {
56:   try {
57:     return execSync(cmd, { stdio: ['ignore', 'pipe', 'pipe'] });
58:   } catch (err) {
59:     throw new Error('Command failed: ' + cmd + '\n' + (err.stderr ? err.stderr.toString('utf8') : err.message));
60:   }
61: }
62: 
63: function main() {
64:   console.log('\n' + C.bold + C.cyan + '================================================================' + C.reset);
65:   console.log(C.bold + C.cyan + '   CINEJOY PRODUCTION UNIFIED IPK VERIFICATION HARNESS         ' + C.reset);
66:   console.log(C.bold + C.cyan + '================================================================' + C.reset + '\n');
67: 
68:   console.log('Target IPK: ' + targetIpk);
69: 
70:   // Step 1: File Existence & Size
71:   process.stdout.write('  [1/7] Validating IPK file existence and minimum size ... ');
72:   assert(fs.existsSync(targetIpk), 'IPK file not found at: ' + targetIpk);
73:   const stat = fs.statSync(targetIpk);
74:   assert(stat.size > 50000, 'IPK file size suspiciously small: ' + stat.size + ' bytes');
75:   console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + (stat.size / 1024).toFixed(1) + ' KB)' + C.reset);
76: 
77:   // Step 2: Archive Container Format (Debian binary format)
78:   process.stdout.write('  [2/7] Verifying ar archive members (debian-binary, control, data) ... ');
79:   const arList = runCommand('ar -t "' + targetIpk + '"');
80:   const arMembers = arList.split('\n').map(function (s) { return s.trim(); }).filter(Boolean);
81:   assert(arMembers.indexOf('debian-binary') !== -1, 'Missing debian-binary member');
82:   assert(arMembers.indexOf('control.tar.gz') !== -1, 'Missing control.tar.gz member');
83:   assert(arMembers.indexOf('data.tar.gz') !== -1, 'Missing data.tar.gz member');
84:   console.log(C.green + C.bold + '✔ PASS' + C.reset);
85: 
86:   // Step 3: Control Metadata Validation
87:   process.stdout.write('  [3/7] Inspecting control.tar.gz metadata ... ');
88:   const controlContent = runCommand('ar -p "' + targetIpk + '" control.tar.gz | tar -zxf - control -O');
89:   assert(controlContent.indexOf('Package: com.cinejoy.tv') !== -1, 'Missing Package: com.cinejoy.tv in control file');
90:   assert(/Version: 1\.0\.[01]/.test(controlContent), 'Missing Version: 1.0.0 or 1.0.1 in control file');
91:   assert(controlContent.indexOf('Architecture: all') !== -1, 'Expected Architecture: all in control file');
92:   console.log(C.green + C.bold + '✔ PASS' + C.reset);
93: 
94:   // Step 4: Data Directory Layout Validation
95:   process.stdout.write('  [4/7] Checking required application and service paths in data.tar.gz ... ');
96:   const dataList = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -ztvf -');
97:   const expectedEntries = [
98:     'usr/palm/applications/com.cinejoy.tv/appinfo.json',
99:     'usr/palm/applications/com.cinejoy.tv/index.html',
100:     'usr/palm/applications/com.cinejoy.tv/js/config.js',
101:     'usr/palm/applications/com.cinejoy.tv/js/app.js',
102:     'usr/palm/packages/com.cinejoy.tv/packageinfo.json',
103:     'usr/palm/services/com.cinejoy.tv.service/services.json',
104:     'usr/palm/services/com.cinejoy.tv.service/package.json',
105:     'usr/palm/services/com.cinejoy.tv.service/index.js',
106:     'usr/palm/services/com.cinejoy.tv.service/resolver.js',
107:     'usr/palm/services/com.cinejoy.tv.service/hls-proxy.js',
108:     'usr/palm/services/com.cinejoy.tv.service/http-client.js',
109:     'usr/palm/services/com.cinejoy.tv.service/crush.wasm'
110:   ];
111: 
112:   for (let i = 0; i < expectedEntries.length; i++) {
113:     const entry = expectedEntries[i];
114:     assert(dataList.indexOf(entry) !== -1, 'Required entry missing from IPK: ' + entry);
115:   }
116:   console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(' + expectedEntries.length + '/' + expectedEntries.length + ' entries verified)' + C.reset);
117: 
118:   // Step 5: Exact crush.wasm Byte Size Check
119:   process.stdout.write('  [5/7] Verifying crush.wasm binary integrity (exactly 67,222 bytes) ... ');
120:   const wasmBuf = runBufferCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/crush.wasm -O');
121:   assert(wasmBuf.length === 67222, 'crush.wasm size mismatch: expected 67222 bytes, got ' + wasmBuf.length);
122:   // Verify WebAssembly magic header \0asm
123:   assert(wasmBuf[0] === 0x00 && wasmBuf[1] === 0x61 && wasmBuf[2] === 0x73 && wasmBuf[3] === 0x6d, 'Invalid WASM magic header in crush.wasm');
124:   console.log(C.green + C.bold + '✔ PASS' + C.reset + ' ' + C.gray + '(67,222 bytes, magic \\0asm valid)' + C.reset);
125: 
126:   // Step 6: Manifest Cross-Validation
127:   process.stdout.write('  [6/7] Cross-validating packageinfo.json, appinfo.json, services.json ... ');
128: 
129:   // Read packageinfo.json
130:   const pkgRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/packages/com.cinejoy.tv/packageinfo.json -O');
131:   const pkgJson = JSON.parse(pkgRaw);
132:   assert(pkgJson.id === 'com.cinejoy.tv', 'packageinfo.json id mismatch: ' + pkgJson.id);
133:   assert(pkgJson.app === 'com.cinejoy.tv', 'packageinfo.json app mismatch: ' + pkgJson.app);
134:   assert(Array.isArray(pkgJson.services) && pkgJson.services.indexOf('com.cinejoy.tv.service') !== -1, 'packageinfo.json missing service com.cinejoy.tv.service');
135: 
136:   // Read appinfo.json
137:   const appRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/applications/com.cinejoy.tv/appinfo.json -O');
138:   const appJson = JSON.parse(appRaw);
139:   assert(appJson.id === 'com.cinejoy.tv', 'appinfo.json id mismatch: ' + appJson.id);
140:   assert(appJson.version === '1.0.0' || appJson.version === '1.0.1', 'appinfo.json version mismatch: ' + appJson.version);
141:   assert(appJson.main === 'index.html', 'appinfo.json main mismatch: ' + appJson.main);
142:   assert(appJson.resolution === '1920x1080', 'appinfo.json resolution mismatch: ' + appJson.resolution);
143: 
144:   // Read services.json
145:   const srvRaw = runCommand('ar -p "' + targetIpk + '" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/services.json -O');
146:   const srvJson = JSON.parse(srvRaw);
147:   assert(srvJson.id === 'com.cinejoy.tv.service', 'services.json id mismatch: ' + srvJson.id);
148:   assert(Array.isArray(srvJson.services) && srvJson.services[0].name === 'com.cinejoy.tv.service', 'services.json service registration mismatch');
149:   console.log(C.green + C.bold + '✔ PASS' + C.reset);
150: 
151:   // Step 7: ares-package Inspection Compatibility
152:   process.stdout.write('  [7/7] Verifying SDK tooling compatibility (ares-package -I) ... ');
153:   const aresOutput = runCommand('ares-package -I "' + targetIpk + '"');
154:   assert(aresOutput.indexOf('< packageinfo.json >') !== -1, 'ares-package -I failed to parse packageinfo.json');
155:   assert(aresOutput.indexOf('< appinfo.json >') !== -1, 'ares-package -I failed to parse appinfo.json');
156:   assert(aresOutput.indexOf('< services.json >') !== -1, 'ares-package -I failed to parse services.json');
157:   console.log(C.green + C.bold + '✔ PASS' + C.reset);
158: 
159:   console.log('\n' + C.green + C.bold + 'IPK VERIFICATION SUCCESS: ' + targetIpk + ' is fully compliant and ready for TV deployment!' + C.reset + '\n');
160: }
161: 
162: try {
163:   main();
164:   process.exit(0);
165: } catch (err) {
166:   console.error('\n' + C.red + C.bold + '✖ IPK VERIFICATION FAILED:' + C.reset + ' ' + err.message + '\n');
167:   process.exit(1);
168: }
